<?php require_once __DIR__.'/../includes/auth.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);$st=$pdo->prepare('SELECT p.*,c.name category_name,s.name supplier_name FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN suppliers s ON s.id=p.supplier_id WHERE p.id=?');$st->execute([$id]);$r=$st->fetch();if(!$r){flash('error','Product not found.');redirect('index.php');}$st=$pdo->prepare('SELECT sm.*,u.full_name FROM stock_movements sm LEFT JOIN users u ON u.id=sm.user_id WHERE product_id=? ORDER BY sm.id DESC LIMIT 10');$st->execute([$id]);$moves=$st->fetchAll();$pageTitle='Product details';$base='/shop-inventory-management';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';?>
<div class="page-heading"><div><h1><?=e($r['name'])?></h1><p>SKU: <?=e($r['sku'])?></p></div><div><a class="btn" href="index.php">← Back</a> <a class="btn primary" href="edit.php?id=<?=$id?>">Edit product</a></div></div><div class="detail-grid"><div class="panel detail-card"><h2>Product information</h2><?php foreach(['SKU'=>'sku','Category'=>'category_name','Supplier'=>'supplier_name','Purchase price'=>'purchase_price','Selling price'=>'selling_price','Available stock'=>'quantity','Minimum stock'=>'minimum_stock','Created'=>'created_at','Updated'=>'updated_at'] as $label=>$key):?><p><span><?=e($label)?></span><strong><?=in_array($key,['purchase_price','selling_price'])?money($r[$key]):e($r[$key]??'—')?></strong></p><?php endforeach;?><p><span>Description</span><strong><?=nl2br(e($r['description']?:'—'))?></strong></p></div><div class="panel"><div class="panel-header"><div><h2>Stock movement history</h2><p>Recent stock changes</p></div><a class="btn small" href="/shop-inventory-management/inventory/adjust_stock.php?id=<?=$id?>">Adjust stock</a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Change</th><th>Reason</th><th>User</th></tr></thead><tbody><?php if(!$moves):?><tr><td colspan="4" class="empty">No stock movements recorded.</td></tr><?php else:foreach($moves as $m):?><tr><td><?=e($m['created_at'])?></td><td class="<?=$m['quantity_change']>0?'text-green':'text-red'?>"><?=$m['quantity_change']>0?'+':''?><?=$m['quantity_change']?></td><td><?=e($m['reason'])?></td><td><?=e($m['full_name']??'System')?></td></tr><?php endforeach;endif;?></tbody></table></div></div></div><?php require __DIR__.'/../includes/footer.php';?>
